import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';import crypto from 'node:crypto';import{fileURLToPath}from'node:url';
import {eighthLeaf,eighthHash} from '../eighth-reconciliation/verify-dependencies.mjs';
const here=path.dirname(fileURLToPath(import.meta.url));const pos=process.argv.indexOf('--dist');assert.ok(pos>=0,'Explicit --dist required');const dist=path.resolve(process.argv[pos+1]);assert.equal(process.argv.length,4,'Only --dist is supported; no overlay/candidate mode');
const read=n=>JSON.parse(fs.readFileSync(path.join(here,n),'utf8'));const sha=s=>crypto.createHash('sha256').update(s).digest('hex');
const afterPrefix=read('fifth-workflow-after-prefix.json');
const physicalRaw=fs.readFileSync(path.join(here,'phase4-physical-condition-reconciliation.json'));assert.equal(sha(physicalRaw),'512d4843d5becec35c8ad6f3554ce2d7c8f8b1bff80a2aeb26df20ea847c631e');const physical=JSON.parse(physicalRaw);
const finalWitness=w=>w.html===physical.oldExactParagraph?physical.newExactParagraph:w.html;
const dagReconciliation=read('phase2-dag-witness-reconciliation.json');
const records=read('records.json').records,app=read('append-manifest.json'),sm=read('source-block-map.json'),vm=read('variant-map.json'),dest=read('destinations.json').destinations,id=read('identity-baseline.json');
const es=new Map();for(const f of fs.readdirSync(path.join(dist,'data/chapters')).filter(f=>f.endsWith('.json')))for(const e of JSON.parse(fs.readFileSync(path.join(dist,'data/chapters',f))).entries){assert.ok(!es.has(e.id),'duplicate entry');es.set(e.id,e);}
const get=key=>{const i=key.lastIndexOf('#'),e=es.get(key.slice(0,i)),q=key.slice(i+1);assert.ok(e,'missing entry '+key);const x=/^\d+$/.test(q)?e.items?.[Number(q)]:e.items?.find(x=>x.id===q);assert.ok(x,'missing question '+key);return x;};
const checks=[];const check=(name,fn)=>{try{checks.push({name,status:'passed',...fn()});}catch(e){checks.push({name,status:'failed',error:e.message});}};
check('dag-old-witness-reconciliation',()=>{const p=dagReconciliation,r=p.record;assert.equal(p.rows.length,4);assert.equal(p.originalDestination.witnesses.length,4);assert.equal(new Set(p.rows.map(x=>x.witnessIndex)).size,4);assert.equal(sha(r.before),p.originalDestination.observedBodySha256);assert.equal(sha(r.after),r.afterSha256);assert.equal(get('ai-agent-5#11').a,eighthLeaf(r.entryId,r.path,r.after));assert.deepEqual(dest.dag,p.expectedDestination);assert.equal(sha(fs.readFileSync(path.join(here,'source-block-map.json'))),p.sourceBlockMapSha256);assert.equal(sha(fs.readFileSync(path.join(here,'variant-map.json'))),p.variantMapSha256);for(const row of p.rows){assert.deepEqual(row.originalWitness,p.originalDestination.witnesses[row.witnessIndex]);assert.equal(sha(row.originalWitness.html),row.originalWitness.sha256);assert.ok(r.before.includes(row.originalWitness.html));assert.ok(row.evidence.length);for(const e of row.evidence){assert.ok(e.html.startsWith('<p'));assert.equal(sha(e.html),e.sha256);assert.ok(get('ai-agent-5#11').a.includes(e.html));assert.ok(dest.dag.witnesses.some(w=>w.html===e.html&&w.sha256===e.sha256));}}return{oldWitnesses:4,newExactParagraphs:dest.dag.witnesses.length,sourceBlocksPreserved:247,variantWordingsPreserved:151};});
check('workflow-composed-after-prefix',()=>{const p=afterPrefix;assert.deepEqual(records[0],p.composedRecord);assert.equal(sha(p.originalRecord.after),p.originalAfterSha256);assert.equal(p.originalRecord.afterSha256,p.originalAfterSha256);assert.equal(sha(p.exactAppendixHtml),p.appendixSha256);assert.equal(p.composedRecord.after,p.originalRecord.after+p.exactAppendixHtml);assert.equal(sha(p.composedRecord.after),p.newAfterSha256);assert.deepEqual({...p.composedRecord,after:p.originalRecord.after,afterSha256:p.originalRecord.afterSha256},p.originalRecord);assert.equal(Array.from(p.exactAppendixHtml).length,p.appendixCodePoints);assert.equal(p.appendixCodePoints,735);assert.equal(p.composedRecord.after,physical.beforeBody);assert.equal(sha(physical.beforeBody),physical.beforeSha256);assert.equal(physical.beforeBody.split(physical.oldExactSubstring).length,2);assert.equal(physical.afterBody,physical.beforeBody.replace(physical.oldExactSubstring,physical.newExactSubstring));assert.equal(sha(physical.afterBody),physical.afterSha256);assert.equal(physical.newExactParagraph,physical.oldExactParagraph.replace(physical.oldExactSubstring,physical.newExactSubstring));assert.ok(physical.newExactSubstring.includes('延迟与传感器错误处理'));assert.equal(get('ai-agent-5#3').a,eighthLeaf(physical.entryId,physical.path,physical.afterBody));assert.ok(physical.afterBody.endsWith(p.exactAppendixHtml));assert.deepEqual(physical.sourceBlock47,sm.blocks[47]);assert.deepEqual(physical.originalRolesWitness,dest.roles.witnesses[1]);assert.equal(sha(fs.readFileSync(path.join(here,'source-block-map.json'))),physical.sourceBlockMapSha256);assert.equal(sha(fs.readFileSync(path.join(here,'variant-map.json'))),physical.variantMapSha256);return{originalAfterFullPrefix:true,appendixCodePoints:735,onlyExactApprovedPhysicalConditionRepair:true};});
check('four-exact-after-leaves',()=>{assert.equal(records.length,4);for(const r of records){assert.equal(sha(r.before),r.beforeSha256);assert.equal(sha(r.after),r.afterSha256);assert.equal(sha(get(r.stableReviewKey).a),eighthHash(r.entryId,r.path,r.stableReviewKey==='ai-agent-5#3'?physical.afterSha256:r.afterSha256),`actual dist lacks exact reviewed ${r.stableReviewKey}`);}return{leaves:4,overlays:0};});
check('two-real-authored-appends',()=>{assert.equal(app.appends.length,2);const e=es.get(app.entryId);assert.ok(e);for(const x of app.appends){assert.ok(e.items[x.expectedIndex],`missing appended slot ${x.expectedIndex}`);assert.equal(sha(JSON.stringify(e.items[x.expectedIndex])),sha(JSON.stringify(x.expectedItem)));assert.equal(e.items[x.expectedIndex].id,x.questionId);}assert.equal(e.items.length,9);assert.deepEqual(app.afterAppendEntry.items.slice(0,7),app.beforeEntry.items);return{appended:2,oldExactPrefixAtCompiler:7,overlays:0};});
check('old-identities-and-append-prefix',()=>{let n=0;for(const b of id.entries){const e=es.get(b.entryId);assert.ok(e);assert.deepEqual(Object.fromEntries(Object.entries(e).filter(([k])=>!['items','number'].includes(k))),b.entryFields);assert.ok(e.items.length>=b.oldCount);for(let i=0;i<b.oldCount;i++){assert.deepEqual(Object.fromEntries(Object.entries(e.items[i]).filter(([k])=>!['a','lead'].includes(k))),b.identities[i]);n++;}}const e=es.get(app.entryId);assert.deepEqual(e.items.slice(0,7).map(x=>x.id),id.oldScenarioIds);assert.deepEqual(e.items.slice(7).map(x=>x.id),id.newScenarioIds);return{oldQuestionIdentities:n,oldScenarioIdentityPrefix:7};});
check('247-blocks-exact-source-and-semantic-witnesses',()=>{const r=records[0];assert.equal(sha(r.before),sm.sourceBodySha256);const blocks=[...r.before.matchAll(/<(p|h[1-6]|li|summary|pre|table)\b[^>]*>[\s\S]*?<\/\1>/g)];assert.equal(blocks.length,247);assert.equal(sm.blocks.length,247);for(const[i,b]of sm.blocks.entries()){assert.equal(b.sourceBlockIndex,i);assert.equal(blocks[i][0],b.sourceHtml);assert.equal(sha(b.sourceHtml),b.sourceSha256);assert.equal(Array.from(r.before).slice(...b.sourceSpanCodePoints).join(''),b.sourceHtml);assert.ok(b.destinations.length);for(const key of b.destinations){const d=dest[key];assert.ok(d,'unknown destination '+key);for(const w of d.witnesses){assert.equal(sha(w.html),w.sha256);assert.ok(get(d.stableReviewKey).a.includes(finalWitness(w)),`Missing substantive ${key} witness for block ${i}`);}}}return{mappedSourceBlocks:247,destinations:Object.keys(dest).length};});
check('151-exact-folded-wordings-and-real-targets',()=>{assert.equal(vm.variantCount,151);assert.equal(vm.variants.length,151);const source=get('ai-agent-5#3').a;const f=source.match(/<details class="qa-variants"><summary>继续追问（151）<\/summary><ul class="md-list">([\s\S]*?)<\/ul><\/details>/);assert.ok(f);assert.equal([...f[1].matchAll(/<li>/g)].length,151);const esc=s=>s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#x27;');for(const v of vm.variants){assert.equal(sha(v.original),v.originalSha256);assert.ok(f[1].includes('<li>'+esc(v.original)+' '),`lost wording ${v.index}`);for(const key of v.destinations){const d=dest[key];get(d.stableReviewKey);assert.ok(f[1].includes('href="#/e/'+d.stableReviewKey.replace('#','/')+'"'));}}return{sourceVariantBlocks:147,wordings:151,folded:true};});
check('routes-html-and-legacy-anchors',()=>{let routes=0;for(const s of [...records.map(r=>r.after),...app.appends.map(x=>x.expectedItem.a)]){const stack=[],voids=new Set(['br','hr','img','input','meta','link','wbr']);for(const m of s.matchAll(/<(\/?)([A-Za-z][\w-]*)\b[^>]*>/g)){if(m[1])assert.equal(stack.pop(),m[2]);else if(!voids.has(m[2])&&!m[0].endsWith('/>'))stack.push(m[2]);}assert.deepEqual(stack,[]);for(const m of s.matchAll(/href="#\/e\/([^"/]+)(?:\/([^"/]+))?"/g)){assert.ok(es.has(decodeURIComponent(m[1])));if(m[2])get(decodeURIComponent(m[1])+'#'+decodeURIComponent(m[2]));routes++;}}for(const r of records)for(const m of r.before.matchAll(/\bid="([^"]+)"/g))assert.ok(r.after.includes('id="'+m[1]+'"'));return{resolvedRoutes:routes,sourceLegacyAnchors:2};});
check('separate-scenarios-and-unique-contracts',()=>{const main=get('ai-agent-5#3').a.split('<details')[0],exam=get('own-agent-task-scenarios#q-agent-workflow-exam-extraction').a,comic=get('own-agent-task-scenarios#q-agent-workflow-comic-production').a;assert.ok(!main.includes('第一步受理资料'));assert.ok(!main.includes('我会先说明：'));for(const t of ['教学七步','实际项目节点','题号重置','图表归属','OCR 重算','不同幂等边界','切题错与解答错'])assert.ok(exam.includes(t),t);for(const t of ['素材权利','内容版本','job ID','局部','旧人物版本','不自动获得对外发布授权','未知'])assert.ok(comic.includes(t),t);for(const t of ['三枚举合同','不能偷偷加第四类','背景词','提示示例和验证集隔离'])assert.ok(get('ai-模型与评测-2#5').a.includes(t),t);for(const t of ['父级总数若已含子账','tokenizer','待对账'])assert.ok(get(dest.usage.stableReviewKey).a.includes(t),t);for(const t of ['凭证由可信适配层','不是隔离机制','不会','operationId'])if(t!=='不会')assert.ok(main.includes(t),t);return{contracts:'present',rewardHasSubstantiveWitness:dest.reward.witnesses.length>0};});
check('new-conceptual-prose-has-no-code-or-provenance',()=>{const additions=[physical.afterBody,...records.slice(1).map(r=>{assert.ok(r.after.startsWith(r.before));return r.after.slice(r.before.length);}),...app.appends.map(x=>x.expectedItem.a)];for(const s of additions){assert.ok(!/<(?:pre|code|script|iframe|style)\b/i.test(s));assert.ok(!/href="https?:\/\//.test(s));assert.ok(!/编辑来源|迁移记录|本文未复验|以下第一人称表达用于|public reference/i.test(s));}return{newCodeBlocks:0,newExternalReferences:0,newProvenanceBoilerplate:0};});
const result={mode:'final',dist,siteWrites:0,overlays:0,recordsSha256:sha(fs.readFileSync(path.join(here,'records.json'))),verifierSha256:sha(fs.readFileSync(fileURLToPath(import.meta.url))),passed:checks.filter(x=>x.status==='passed').length,failed:checks.filter(x=>x.status==='failed').length,total:checks.length,actualFinalDistAcceptance:checks.every(x=>x.status==='passed'),checks};console.log(JSON.stringify(result,null,2));if(result.failed)process.exitCode=1;
